class CommissionComplaintsCenterScreen extends ConsumerWidget{
 const CommissionComplaintsCenterScreen({super.key,required this.profile});final EmployeeProfile profile;
 bool get _owner=>profile.role==EmployeeRole.owner;
 @override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Commission Complaints')),floatingActionButton:(!_owner)?FloatingActionButton.extended(onPressed:()=>_newComplaint(context,ref),icon:const Icon(Icons.add),label:const Text('New complaint')):null,body:RefreshIndicator(onRefresh:()async=>ref.invalidate(complaintThreadsProvider),child:ref.watch(complaintThreadsProvider).when(data:(items)=>items.isEmpty?ListView(children:[const SizedBox(height:120),const Center(child:Text('No commission complaints.'))]):ListView(padding:const EdgeInsets.all(12),children:[if(_owner)Padding(padding:const EdgeInsets.all(8),child:Text('${items.where((c)=>c.status=='open').length} open · ${items.where((c)=>c.status=='resolved').length} resolved · ${items.where((c)=>c.status=='rejected').length} rejected',style:Theme.of(context).textTheme.titleMedium)),...items.map((c)=>Card(child:ListTile(leading:Icon(c.status=='resolved'?Icons.check_circle:c.status=='rejected'?Icons.cancel:Icons.pending_actions),title:Text(c.type.replaceAll('_',' ').toUpperCase()),subtitle:Text('${c.employeeName??'My complaint'} · ${c.status.toUpperCase()}\n${c.message}',maxLines:3,overflow:TextOverflow.ellipsis),isThreeLine:true,onTap:()=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>_ComplaintDetails(profile:profile,complaint:c)))))]),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('Complaints unavailable: $e')))));
 Future<void> _newComplaint(BuildContext context,WidgetRef ref)async{final client=Supabase.instance.client;final commissions=await client.from('commissions').select('id,period_month,amount,currency,status').order('period_month',ascending:false).limit(100);if(!context.mounted)return;if(commissions.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No commission record is available to attach a complaint to.')));return;}final message=TextEditingController();final expected=TextEditingController();String commissionId=commissions.first['id'].toString(),type='not_received';PlatformFile? attachment;
 final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:const Text('New commission complaint'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:type,items:const[DropdownMenuItem(value:'not_received',child:Text('Not received')),DropdownMenuItem(value:'wrong_amount',child:Text('Wrong amount')),DropdownMenuItem(value:'late_payment',child:Text('Late payment')),DropdownMenuItem(value:'other',child:Text('Other'))],onChanged:(v)=>setD(()=>type=v??type),decoration:const InputDecoration(labelText:'Complaint type')),DropdownButtonFormField<String>(value:commissionId,items:commissions.map((c)=>DropdownMenuItem(value:c['id'].toString(),child:Text('${c['period_month']} · LKR ${c['amount']}'))).toList(),onChanged:(v)=>setD(()=>commissionId=v??commissionId),decoration:const InputDecoration(labelText:'Commission record')),TextField(controller:message,minLines:3,maxLines:5,decoration:const InputDecoration(labelText:'Explain the issue')),TextField(controller:expected,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Expected amount (optional)')),OutlinedButton.icon(onPressed:()async{final f=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:const['jpg','jpeg','png','webp','pdf'],withData:true);if(f!=null)setD(()=>attachment=f.files.single);},icon:const Icon(Icons.attach_file),label:Text(attachment?.name??'Attach screenshot / PDF'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Submit'))]));
 if(ok!=true||message.text.trim().length<3)return;try{await ref.read(businessCenterRepositoryProvider).submitComplaint(commissionId:commissionId,type:type,message:message.text,expectedAmount:double.tryParse(expected.text),attachment:attachment?.bytes,fileName:attachment?.name);ref.invalidate(complaintThreadsProvider);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Complaint submitted.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Submission failed: $e')));}
 }
}
class _ComplaintDetails extends ConsumerStatefulWidget{const _ComplaintDetails({required this.profile,required this.complaint});final EmployeeProfile profile;final CommissionComplaintThread complaint;@override ConsumerState<_ComplaintDetails> createState()=>_ComplaintDetailsState();}
class _ComplaintDetailsState extends ConsumerState<_ComplaintDetails>{final _message=TextEditingController();final _resolution=TextEditingController();bool busy=false;bool get owner=>widget.profile.role==EmployeeRole.owner;
 @override void dispose(){_message.dispose();_resolution.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Complaint Details')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.complaint.type.replaceAll('_',' ').toUpperCase(),style:Theme.of(context).textTheme.titleLarge),Text('Status: ${widget.complaint.status.toUpperCase()}'),Text('Employee: ${widget.complaint.employeeName??widget.profile.fullName}'),const SizedBox(height:8),Text(widget.complaint.message),if(widget.complaint.expectedAmount!=null)Text('Expected amount: LKR ${widget.complaint.expectedAmount!.toStringAsFixed(2)}'),if(widget.complaint.ownerResponse!=null)Text('Owner response: ${widget.complaint.ownerResponse}')])),FutureBuilder<List<Map<String,dynamic>>>(future:ref.read(businessCenterRepositoryProvider).complaintMessages(widget.complaint.id),builder:(context,s)=>s.connectionState!=ConnectionState.done?const LinearProgressIndicator():s.hasError?Text('Messages unavailable: ${s.error}'):Column(children:(s.data??[]).map((m)=>ListTile(title:Text(m['sender']?['name']?.toString()??'Employee'),subtitle:Text(m['message'].toString()),trailing:Text(m['created_at'].toString().substring(0,10),style:const TextStyle(fontSize:10)))).toList())),TextField(controller:_message,decoration:const InputDecoration(labelText:'Add message'),maxLines:2),FilledButton(onPressed:busy?null:()async{setState(()=>busy=true);try{await ref.read(businessCenterRepositoryProvider).addComplaintMessage(widget.complaint.id,_message.text);_message.clear();setState((){});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Message sent.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Message failed: $e')));}finally{if(mounted)setState(()=>busy=false);}},child:const Text('Send message')),if(owner&&widget.complaint.status=='open')... [TextField(controller:_resolution,decoration:const InputDecoration(labelText:'Resolution note'),maxLines:3),Row(children:[Expanded(child:OutlinedButton(onPressed:busy?null:()=>_resolve(true),child:const Text('Reject'))),const SizedBox(width:10),Expanded(child:FilledButton(onPressed:busy?null:()=>_resolve(false),child:const Text('Resolve')))])],const SizedBox(height:16),if(widget.complaint.status!='open')Text('Complaint is ${widget.complaint.status}.')]));
 Future<void> _resolve(bool reject)async{setState(()=>busy=true);try{await ref.read(businessCenterRepositoryProvider).resolveComplaint(widget.complaint.id,reject:reject,response:_resolution.text);ref.invalidate(complaintThreadsProvider);if(mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(reject?'Complaint rejected.':'Complaint resolved.')));Navigator.pop(context);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Resolution failed: $e')));}finally{if(mounted)setState(()=>busy=false);}}
}
